/** Text of a PDF without external libraries: Flate/ASCII85 streams, object streams, the page tree and ToUnicode maps.
 *  Scanned pages, encrypted files and fonts without a usable encoding give little or no text; nothing is executed. */
final class PdfText{
 static final int MAX_BYTES=33554432,MAX_STREAM=50331648,MAX_PAGES=5000;
 static final class Obj{String dict="";int streamStart=-1,streamEnd=-1;byte[] inline;}
 static final class Font{final Map<Integer,String> map=new HashMap<>();int width=1;}
 final byte[] data;final Map<Integer,Obj> objects=new HashMap<>();final Map<Integer,Font> fonts=new HashMap<>();final PageStream.Budget budget;final StringBuilder out=new StringBuilder();long produced;
 PdfText(byte[] bytes,PageStream.Budget b){data=bytes;budget=b;}
 static String latin(byte[] b,int from,int to){char[] c=new char[to-from];for(int i=from;i<to;i++)c[i-from]=(char)(b[i]&255);return new String(c);}
 static int find(byte[] hay,String needle,int from,int limit){byte[] n=needle.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);outer:for(int i=Math.max(0,from);i+n.length<=limit;i++){for(int j=0;j<n.length;j++)if(hay[i+j]!=n[j])continue outer;return i;}return -1;}
 static String extract(byte[] pdf,PageStream.Budget budget)throws Exception{if(pdf.length>MAX_BYTES)throw new IOException("El PDF supera32 MiB");if(pdf.length<8||find(pdf,"%PDF-",0,Math.min(pdf.length,1024))<0)throw new IOException("El archivo no es un PDF válido");PdfText p=new PdfText(pdf,budget);p.scan();p.pages();String text=p.out.toString().replaceAll("[ \\t\\u00a0]+"," ").replaceAll(" ?\\n ?","\n").replaceAll("\\n{3,}","\n\n").trim();if(text.replaceAll("\\s","").length()<40)throw new IOException("No se encontro texto util en el PDF; puede estar escaneado como imagen o usar fuentes sin tabla de caracteres");return text;}
 /** Every «n g obj» in the file, then the objects packed inside object streams. */
 void scan()throws Exception{int n=data.length,i=0,count=0;while(i<n){int at=find(data," obj",i,n);if(at<0)break;int s=at-1;while(s>=0&&data[s]>='0'&&data[s]<='9')s--;int genStart=s+1;if(s<0||data[s]!=' '||genStart==at){i=at+4;continue;}int e=s-1;while(e>=0&&data[e]>='0'&&data[e]<='9')e--;if(e+1==s){i=at+4;continue;}int num;try{num=Integer.parseInt(latin(data,e+1,s));}catch(Exception bad){i=at+4;continue;}
   int body=at+4,end=find(data,"endobj",body,n);if(end<0)end=n;int stream=find(data,"stream",body,end);Obj o=new Obj();if(stream>=0&&find(data,"endstream",stream,Math.min(n,end+16))>=0||stream>=0&&end==n){int start=stream+6;if(start<n&&data[start]=='\r')start++;if(start<n&&data[start]=='\n')start++;int stop=find(data,"endstream",start,n);if(stop<0)stop=n;o.dict=latin(data,body,stream);o.streamStart=start;o.streamEnd=stop;end=find(data,"endobj",stop,n);if(end<0)end=stop;}else o.dict=latin(data,body,end);
   objects.put(num,o);if(++count>200000)throw new IOException("PDF con demasiados objetos");if((count&255)==0)budget.check();i=end+6;}
  if(objects.isEmpty())throw new IOException("El PDF no tiene objetos legibles");for(Obj o:objects.values())if(o.dict.contains("/Encrypt"))throw new IOException("El PDF está protegido con contraseña o cifrado; no lo leo");if(find(data,"/Encrypt",Math.max(0,n-4096),n)>=0)throw new IOException("El PDF está protegido con contraseña o cifrado; no lo leo");
  List<Integer> packed=new ArrayList<>();for(Map.Entry<Integer,Obj> e:objects.entrySet())if(e.getValue().dict.contains("/ObjStm"))packed.add(e.getKey());
  for(int id:packed){Obj holder=objects.get(id);byte[] raw=stream(holder);if(raw==null)continue;Matcher nm=Pattern.compile("/N\\s+(\\d+)").matcher(holder.dict),fm=Pattern.compile("/First\\s+(\\d+)").matcher(holder.dict);if(!nm.find()||!fm.find())continue;int total=Integer.parseInt(nm.group(1)),first=Integer.parseInt(fm.group(1));if(first>raw.length||total>100000)continue;String[] head=latin(raw,0,first).trim().split("\\s+");for(int k=0;k+1<head.length&&k/2<total;k+=2){try{int num=Integer.parseInt(head[k]),off=first+Integer.parseInt(head[k+1]),next=k+3<head.length&&(k+2)/2<total?first+Integer.parseInt(head[k+3]):raw.length;if(off<0||off>raw.length||next<off||next>raw.length||objects.containsKey(num)&&objects.get(num).streamStart>=0)continue;Obj o=new Obj();o.dict=latin(raw,off,next);objects.put(num,o);}catch(NumberFormatException bad){break;}}budget.check();}}
 int number(String dict,String key){Matcher m=Pattern.compile(Pattern.quote(key)+"\\s+(\\d+)(\\s+\\d+\\s+R)?").matcher(dict);if(!m.find())return -1;int v=Integer.parseInt(m.group(1));if(m.group(2)!=null){Obj o=objects.get(v);if(o==null)return -1;Matcher d=Pattern.compile("^\\s*(\\d+)").matcher(o.dict);return d.find()?Integer.parseInt(d.group(1)):-1;}return v;}
 /** Decoded stream bytes, or null when the filter is not supported (images, LZW, …). */
 byte[] stream(Obj o)throws Exception{if(o==null||o.streamStart<0)return o==null?null:o.inline;int start=o.streamStart,end=o.streamEnd;int length=number(o.dict,"/Length");if(length>=0&&start+length<=data.length&&start+length<=end+2)end=start+length;else{while(end>start&&(data[end-1]=='\n'||data[end-1]=='\r'))end--;}byte[] raw=Arrays.copyOfRange(data,start,Math.max(start,end));Matcher f=Pattern.compile("/Filter\\s*(\\[[^\\]]*\\]|/[A-Za-z0-9]+)").matcher(o.dict);if(!f.find())return raw;if(o.dict.contains("/Predictor")&&!o.dict.matches("(?s).*/Predictor\\s+1\\b.*"))return null;
  Matcher names=Pattern.compile("/([A-Za-z0-9]+)").matcher(f.group(1));while(names.find()){String name=names.group(1);if(name.equals("FlateDecode")||name.equals("Fl"))raw=inflate(raw);else if(name.equals("ASCII85Decode")||name.equals("A85"))raw=ascii85(raw);else if(name.equals("ASCIIHexDecode")||name.equals("AHx"))raw=hex(latin(raw,0,raw.length));else return null;if(raw==null)return null;}return raw;}
 byte[] inflate(byte[] raw)throws Exception{Inflater inf=new Inflater();inf.setInput(raw);ByteArrayOutputStream o=new ByteArrayOutputStream(Math.min(MAX_STREAM,raw.length*3+64));byte[] b=new byte[16384];try{while(!inf.finished()){int n=inf.inflate(b);if(n==0&&(inf.needsInput()||inf.needsDictionary()))break;o.write(b,0,n);if(o.size()>MAX_STREAM)throw new IOException("Un bloque del PDF supera el límite al descomprimir");budget.check();}}catch(DataFormatException partial){if(o.size()==0)return null;}finally{inf.end();}return o.toByteArray();}
 static byte[] ascii85(byte[] raw){ByteArrayOutputStream o=new ByteArrayOutputStream(raw.length);long group=0;int count=0;for(int i=0;i<raw.length;i++){int c=raw[i]&255;if(c=='~')break;if(c<=' ')continue;if(c=='z'&&count==0){o.write(0);o.write(0);o.write(0);o.write(0);continue;}if(c<'!'||c>'u')return null;group=group*85+(c-'!');if(++count==5){o.write((int)(group>>24)&255);o.write((int)(group>>16)&255);o.write((int)(group>>8)&255);o.write((int)group&255);group=0;count=0;}}if(count>1){for(int k=count;k<5;k++)group=group*85+84;for(int k=0;k<count-1;k++)o.write((int)(group>>(24-8*k))&255);}return o.toByteArray();}
 static byte[] hex(String s){ByteArrayOutputStream o=new ByteArrayOutputStream(s.length()/2+1);int hi=-1;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c=='>')break;int v=Character.digit(c,16);if(v<0)continue;if(hi<0)hi=v;else{o.write(hi*16+v);hi=-1;}}if(hi>=0)o.write(hi*16);return o.toByteArray();}
 static String utf16(byte[] b){StringBuilder s=new StringBuilder();for(int i=0;i+1<b.length;i+=2)s.append((char)(((b[i]&255)<<8)|(b[i+1]&255)));if(b.length==1)s.append((char)(b[0]&255));return s.toString();}
 static int code(byte[] b){int v=0;for(byte x:b)v=(v<<8)|(x&255);return v;}
 /** bfchar and bfrange sections of a ToUnicode CMap. */
 Font cmap(int ref)throws Exception{Font cached=fonts.get(ref);if(cached!=null)return cached;Font font=new Font();fonts.put(ref,font);byte[] raw=stream(objects.get(ref));if(raw==null)return font;String s=latin(raw,0,Math.min(raw.length,4000000));Matcher space=Pattern.compile("begincodespacerange\\s*<([0-9A-Fa-f]+)>").matcher(s);if(space.find())font.width=Math.max(1,Math.min(2,space.group(1).length()/2));
  Matcher section=Pattern.compile("(?s)beginbfchar(.*?)endbfchar").matcher(s);while(section.find()){Matcher pair=Pattern.compile("<([0-9A-Fa-f]+)>\\s*<([0-9A-Fa-f]*)>").matcher(section.group(1));while(pair.find()){font.map.put(code(hex(pair.group(1))),utf16(hex(pair.group(2))));if(pair.group(1).length()>2)font.width=2;}}
  section=Pattern.compile("(?s)beginbfrange(.*?)endbfrange").matcher(s);while(section.find()){Matcher r=Pattern.compile("<([0-9A-Fa-f]+)>\\s*<([0-9A-Fa-f]+)>\\s*(?:<([0-9A-Fa-f]*)>|\\[([^\\]]*)\\])").matcher(section.group(1));while(r.find()){int lo=code(hex(r.group(1))),hi=code(hex(r.group(2)));if(r.group(1).length()>2)font.width=2;if(hi<lo||hi-lo>65535)continue;if(r.group(3)!=null){String base=utf16(hex(r.group(3)));if(base.isEmpty())continue;for(int c=lo;c<=hi;c++)font.map.put(c,base.substring(0,base.length()-1)+(char)(base.charAt(base.length()-1)+(c-lo)));}else{Matcher item=Pattern.compile("<([0-9A-Fa-f]*)>").matcher(r.group(4));int c=lo;while(item.find()&&c<=hi)font.map.put(c++,utf16(hex(item.group(1))));}}budget.check();}
  return font;}
 static final String CP1252="\u20ac\u0081\u201a\u0192\u201e\u2026\u2020\u2021\u02c6\u2030\u0160\u2039\u0152\u008d\u017d\u008f\u0090\u2018\u2019\u201c\u201d\u2022\u2013\u2014\u02dc\u2122\u0161\u203a\u0153\u009d\u017e\u0178";
 String decode(byte[] bytes,Font font){StringBuilder s=new StringBuilder();if(font!=null&&!font.map.isEmpty()){int w=font.width;for(int i=0;i+w<=bytes.length;i+=w){int c=w==2?((bytes[i]&255)<<8)|(bytes[i+1]&255):bytes[i]&255;String u=font.map.get(c);if(u!=null)s.append(u);else if(w==1&&c>=32)s.append((char)c);}return s.toString();}for(byte b:bytes){int c=b&255;if(c>=0x80&&c<0xa0)s.append(CP1252.charAt(c-0x80));else if(c>=32||c=='\n')s.append((char)c);}return s.toString();}
 Map<String,Font> fontsOf(String dict)throws Exception{Map<String,Font> map=new HashMap<>();String fontDict=null;Matcher inline=Pattern.compile("(?s)/Font\\s*<<(.*?)>>").matcher(dict);if(inline.find())fontDict=inline.group(1);else{Matcher ref=Pattern.compile("/Font\\s+(\\d+)\\s+\\d+\\s+R").matcher(dict);if(ref.find()&&objects.get(Integer.parseInt(ref.group(1)))!=null)fontDict=objects.get(Integer.parseInt(ref.group(1))).dict;}if(fontDict==null)return map;Matcher pair=Pattern.compile("/([^\\s/<>\\[\\]()]+)\\s+(\\d+)\\s+\\d+\\s+R").matcher(fontDict);while(pair.find()){Obj f=objects.get(Integer.parseInt(pair.group(2)));if(f==null)continue;Matcher uni=Pattern.compile("/ToUnicode\\s+(\\d+)\\s+\\d+\\s+R").matcher(f.dict);map.put(pair.group(1),uni.find()?cmap(Integer.parseInt(uni.group(1))):new Font());}return map;}
 String resources(String dict,int depth){if(dict.contains("/Font"))return dict;Matcher ref=Pattern.compile("/Resources\\s+(\\d+)\\s+\\d+\\s+R").matcher(dict);if(ref.find()){Obj r=objects.get(Integer.parseInt(ref.group(1)));if(r!=null)return r.dict;}Matcher parent=Pattern.compile("/Parent\\s+(\\d+)\\s+\\d+\\s+R").matcher(dict);if(depth<32&&parent.find()){Obj p=objects.get(Integer.parseInt(parent.group(1)));if(p!=null)return resources(p.dict,depth+1);}return "";}
 /** Pages in reading order through the page tree; if the tree is unusable, every page object in file order. */
 void pages()throws Exception{List<Integer> order=new ArrayList<>();Integer root=null;for(Map.Entry<Integer,Obj> e:objects.entrySet())if(e.getValue().dict.matches("(?s).*/Type\\s*/Catalog\\b.*")){Matcher m=Pattern.compile("/Pages\\s+(\\d+)\\s+\\d+\\s+R").matcher(e.getValue().dict);if(m.find())root=Integer.parseInt(m.group(1));}if(root!=null)walk(root,order,new HashSet<Integer>(),0);if(order.isEmpty()){List<Integer> ids=new ArrayList<>(objects.keySet());Collections.sort(ids);for(int id:ids)if(objects.get(id).dict.matches("(?s).*/Type\\s*/Page\\b.*"))order.add(id);}
  if(order.isEmpty())throw new IOException("El PDF no tiene páginas legibles");int n=0;for(int id:order){if(++n>MAX_PAGES)break;budget.check();Obj page=objects.get(id);Map<String,Font> pageFonts=fontsOf(resources(page.dict,0));List<Integer> contents=new ArrayList<>();Matcher arr=Pattern.compile("(?s)/Contents\\s*\\[(.*?)\\]").matcher(page.dict);if(arr.find()){Matcher r=Pattern.compile("(\\d+)\\s+\\d+\\s+R").matcher(arr.group(1));while(r.find())contents.add(Integer.parseInt(r.group(1)));}else{Matcher one=Pattern.compile("/Contents\\s+(\\d+)\\s+\\d+\\s+R").matcher(page.dict);if(one.find()){int ref=Integer.parseInt(one.group(1));Obj c=objects.get(ref);if(c!=null&&c.streamStart<0){Matcher r=Pattern.compile("(\\d+)\\s+\\d+\\s+R").matcher(c.dict);while(r.find())contents.add(Integer.parseInt(r.group(1)));}else contents.add(ref);}}
   ByteArrayOutputStream all=new ByteArrayOutputStream();for(int ref:contents){byte[] part=stream(objects.get(ref));if(part!=null){all.write(part);all.write('\n');}}content(all.toByteArray(),pageFonts);out.append("\n\n");if(out.length()>NotebookDisk.DOCUMENT_CHARS)throw new IOException("El texto del PDF supera16000000 caracteres por documento");}}
 void walk(int id,List<Integer> order,Set<Integer> seen,int depth){Obj o=objects.get(id);if(o==null||depth>64||!seen.add(id)||order.size()>MAX_PAGES)return;Matcher kids=Pattern.compile("(?s)/Kids\\s*\\[(.*?)\\]").matcher(o.dict);if(kids.find()){Matcher r=Pattern.compile("(\\d+)\\s+\\d+\\s+R").matcher(kids.group(1));while(r.find())walk(Integer.parseInt(r.group(1)),order,seen,depth+1);}else if(o.dict.contains("/Contents"))order.add(id);}
 /** Text-showing operators of one page. Position changes become spaces or line breaks. */
 void content(byte[] c,Map<String,Font> pageFonts)throws Exception{Font font=null;List<Object> stack=new ArrayList<>();int i=0,n=c.length;double lastY=Double.NaN;long steps=0;
  while(i<n){if((++steps&4095)==0)budget.check();int ch=c[i]&255;if(ch<=' '){i++;continue;}if(ch=='%'){while(i<n&&c[i]!='\n'&&c[i]!='\r')i++;continue;}
   if(ch=='('){ByteArrayOutputStream s=new ByteArrayOutputStream();int depth=1;i++;while(i<n&&depth>0){int b=c[i++]&255;if(b=='\\'&&i<n){int e=c[i++]&255;switch(e){case 'n':s.write('\n');break;case 'r':s.write('\r');break;case 't':s.write('\t');break;case 'b':s.write(8);break;case 'f':s.write(12);break;case '\r':if(i<n&&c[i]=='\n')i++;break;case '\n':break;default:if(e>='0'&&e<='7'){int v=e-'0';for(int k=0;k<2&&i<n&&c[i]>='0'&&c[i]<='7';k++)v=v*8+(c[i++]-'0');s.write(v&255);}else s.write(e);}}else if(b=='('){depth++;s.write(b);}else if(b==')'){if(--depth>0)s.write(b);}else s.write(b);}stack.add(s.toByteArray());continue;}
   if(ch=='<'&&i+1<n&&c[i+1]!='<'){int end=i+1;while(end<n&&c[end]!='>')end++;stack.add(hex(latin(c,i+1,end)));i=Math.min(n,end+1);continue;}
   if(ch=='<'||ch=='>'){i+=2;continue;}if(ch=='['){stack.add("[");i++;continue;}if(ch==']'){int open=stack.lastIndexOf("[");if(open>=0){List<Object> items=new ArrayList<>(stack.subList(open+1,stack.size()));while(stack.size()>open)stack.remove(stack.size()-1);stack.add(items);}i++;continue;}
   int start=i;if(ch=='/'){i++;while(i<n&&" \t\r\n/[]()<>%".indexOf(c[i]&255)<0)i++;stack.add("/"+latin(c,start+1,i));continue;}
   while(i<n&&" \t\r\n/[]()<>%".indexOf(c[i]&255)<0)i++;if(i==start){i++;continue;}String word=latin(c,start,i);char first=word.charAt(0);if(first>='0'&&first<='9'||first=='-'||first=='+'||first=='.'){try{stack.add(Double.valueOf(word));}catch(NumberFormatException bad){}continue;}
   if(word.equals("Tf")){if(stack.size()>=2&&stack.get(stack.size()-2) instanceof String)font=pageFonts.get(((String)stack.get(stack.size()-2)).substring(1));}
   else if(word.equals("Tj")||word.equals("'")||word.equals("\"")){if(!word.equals("Tj"))line();if(!stack.isEmpty()&&stack.get(stack.size()-1) instanceof byte[])emit(decode((byte[])stack.get(stack.size()-1),font));}
   else if(word.equals("TJ")){if(!stack.isEmpty()&&stack.get(stack.size()-1) instanceof List)for(Object item:(List<?>)stack.get(stack.size()-1)){if(item instanceof byte[])emit(decode((byte[])item,font));else if(item instanceof Double&&((Double)item)<-180)emit(" ");}}
   else if(word.equals("Td")||word.equals("TD")){double ty=stack.size()>=1&&stack.get(stack.size()-1) instanceof Double?(Double)stack.get(stack.size()-1):0;if(Math.abs(ty)>.01)line();else emit(" ");}
   else if(word.equals("T*"))line();else if(word.equals("Tm")){double y=stack.size()>=1&&stack.get(stack.size()-1) instanceof Double?(Double)stack.get(stack.size()-1):0;if(!Double.isNaN(lastY)&&Math.abs(y-lastY)>.01)line();else emit(" ");lastY=y;}
   else if(word.equals("ET"))emit(" ");else if(word.equals("BI")){int stop=find(c,"EI",i,n);i=stop<0?n:stop+2;}
   stack.clear();}}
 void emit(String text)throws IOException{produced+=text.length();if(produced>NotebookDisk.DOCUMENT_CHARS)throw new IOException("El texto del PDF supera16000000 caracteres por documento");if(text.equals(" ")){int len=out.length();if(len>0&&out.charAt(len-1)!=' '&&out.charAt(len-1)!='\n')out.append(' ');}else out.append(text);}
 void line(){int len=out.length();if(len>0&&out.charAt(len-1)!='\n')out.append('\n');}
}
